// === Tab: mySketch ===
f=l=0;
draw = (_) => {
  f || createCanvas(V=1412, W=994, WEBGL)
  noStroke(background(255))
	colorMode(HSB)
  h=42
  P=PI
  i=P/27
  for(x=-P;x<P;x+=i){
    for(z=-P;z<P;z+=i){
      push(y = tan(W-mag(noise(x),noise(z))*f))
      scale(5.8)
      translate(x*h,z*h,-y*h*8.5)
			fill((abs(z)*11+abs(x)*180)%360,100,113)
      pop(sphere(mag(noise(x),noise(z))*7.3))
    }
  }
  f+=i/4
}
mousePressed=()=>{if (millis()-l>400){save('pix.jpg');l=millis();}}

